-- Posuđenice (germanizmi, turcizmi, anglizmi) — kategorija Hrvatska. Sigurno za ponovno pokretanje.
on conflict (question) do update set category = excluded.category, answer = excluded.answer,
  aliases = excluded.aliases, wrong = excluded.wrong, usage = excluded.usage;

select count(*) as posudenice from public.questions where question like '%izam „%' or question like 'Iz kojeg jezika dolazi riječ%' or question like 'Kako se zovu riječi preuzete%';
